    const rand = rng(Math.round(W2 * 100 + D2 * 10) + 5);
    const group = new Group();
    group.name = "m4-outdoor";
    ctx.scene.add(group);
    ctx.track(group);
    for (const n of ["lfx-backdrop", "lfx-street"]) {
      const o = ctx.scene.getObjectByName(n);
      if (o) o.visible = false;
    }
    const textures = [];
    const T5 = (c, o) => {
      const t = toTexture(c, { aniso: 2, ...o });
      textures.push(t);
      return t;
    };
    const tinted = [];
    const tint2 = (mat2, base = [1, 1, 1]) => {
      tinted.push({ mat: mat2, base });
      return mat2;
    };
    const windowSets = [];
    const hooks = [];
