    for (let i = 0; i < 420; i++) {
      const a = rand() * PI4 * 2;
      const e = 0.08 + rand() * 0.9;
      const r = FAR_R * 0.96;
      starPos.push(Math.cos(a) * Math.cos(e) * r, Math.sin(e) * r, Math.sin(a) * Math.cos(e) * r);
    }
