    const m = sa.mirror;
    const fz0 = Z1 - T5;
    const FR = [0.78, 0.62, 0.22];
    const mx0 = m.x - m.w / 2;
    const mx1 = m.x + m.w / 2;
    const my0 = m.y - m.h / 2;
    const my1 = m.y + m.h / 2;
