      try {
        if (this.front) {
          art = makeCanvas(256, 384);
          const cx = art.getContext("2d");
          if (cx) cx.drawImage(this.front, 0, 0, 256, 384);
          else art = null;
        }
      } catch {
        art = null;
      }
      this.slot = null;
      this.token++;
      this.finishClose();
      return { slot, art };
